from lib import *
S = SS('u165')
R = J('u165'); run = R['run']; sp = R['speed']; a_ = sp['ASan(默认)']; n_ = sp['--sanitizer none']
ea = a_['stat::average_exec_per_sec']; en = n_['stat::average_exec_per_sec']
steps = [
    step("cargo fuzz init 生成 fuzz/ 目录:一个独立的 Cargo 项目(fuzz/Cargo.toml,依赖 libfuzzer-sys 与被测 crate)和 fuzz/fuzz_targets/ 下的目标文件。目标文件是 #![no_main] + fuzz_target!(|data: &[u8]| { … }),把 fuzzer 生成的字节喂给被测函数。被测的 parse 里藏了一个 bug:输入以 FUZZ!? 开头且长度恰好是 6 时,data[6] 越界。", t=tl(S(1)), mark=lidx(S(1), 'data[6]', 'fuzz_target!'), done=lidx(S(1), 'fuzz/fuzz_targets/parse.rs', 'fuzz/Cargo.toml'), kv=KV([['fuzz/Cargo.toml', '依赖 libfuzzer-sys'], ['目标', 'fuzz_target!(|data: &[u8]| …)'], ['初始语料', '没有']], ['目标'])),
    step(f"cargo fuzz run parse(固定 -seed=1,没有任何初始语料):日志里每个 NEW 是「发现了一个带来新覆盖的输入」。#12 时 cov 从 17 涨到 20,#192 时「DE: \"FUZZ\"」说明变异用了从比较指令里学到的字面量 FUZZ,#8791 起继续增加。覆盖到 cov: 30 后,在第 {run['found_at']} 次执行崩溃:「index out of bounds: the len is 6 but the index is 6」,输入是 0x46,0x55,0x5a,0x5a,0x21,0x3f(FUZZ!?)。含编译共 {run['secs']} 秒。用同一个种子重放并二分 -runs,确认确定性地在第 {run['found_at']} 次执行崩溃(-runs={run['found_at'] - 1} 不崩)。", t=tl(S(2)), done=lidx(S(2), 'NEW', 'INITED'), mark=lidx(S(2), 'index out of bounds', '0x46,0x55', '第 11480'), b=bars([['#12 cov', 20, 'cov 20'], ['#192', 21, 'cov 21'], ['#484', 23, 'cov 23'], ['#696', 25, 'cov 25'], ['#865', 26, 'cov 26'], ['#8791', 27, 'cov 27'], ['#8957', 29, 'cov 29'], ['#8973', 30, 'cov 30']], 30, done=[0, 1, 2, 3, 4, 5, 6, 7]), kv=KV([['崩溃出现在', f"第 {run['found_at']} 次执行"], ['崩溃输入', 'FUZZ!?(6 字节)']], ['崩溃输入'])),
    step("复现与记录:崩溃输入被写进 fuzz/artifacts/parse/crash-<哈希>,内容是 6 个字节 [70, 85, 90, 90, 33, 63] = b'FUZZ!?'。cargo fuzz run parse <文件> 单独重放这个输入,同样 panic,libFuzzer 报「deadly signal」,cargo fuzz 以「exit status: 77」退出(命令退出码 1)。cargo fuzz fmt 把它按 Debug 形式打印出来,可以直接贴进单元测试。", t=tl(S(3)), mark=lidx(S(3), 'index out of bounds', 'exit status: 77'), done=lidx(S(3), '崩溃输入 6 字节', '[70, 85, 90, 90, 33, 63]'), kv=KV([['重放', 'panic,exit status 77'], ['fmt', '[70, 85, 90, 90, 33, 63]']], ['重放'])),
    step("语料库:fuzzer 保存了 8 个「各自带来新覆盖」的输入,最短 4 字节:b'FUZZ'、b'FUZZ\\x03'、b'FUZZ!'、b'FUZZ!Z'、b'FUZZ!FUZZ' 等。可以看到它是一步步靠近的:先学到 FUZZ 这个前缀,再学到第 5 个字节 !,最后组合出 FUZZ!?。语料库放在 fuzz/corpus/parse,下一次运行从它开始,不用从头来。", t=tl(S(4)), done=lidx(S(4), "b'FUZZ'", "b'FUZZ\\x03'", "b'FUZZ!'"), mark=lidx(S(4), "b'FUZZ!Z'", "b'FUZZ!FUZZ'"), kv=KV([['语料文件', '8 个'], ['位置', 'fuzz/corpus/parse']], ['语料文件'])),
    step("最小化:cargo fuzz tmin 对崩溃输入逐字节删除与替换后重试,结果「failed to minimize beyond … (6 bytes)」:这个输入已经是最小的 6 字节。(没有验证:对更长、带冗余字节的崩溃输入的缩减效果;本篇没有构造这样的输入。)", t=tl(S(5)), mark=lidx(S(5), 'failed to minimize'), kv=KV([['tmin', '6 字节已最小']], ['tmin'])),
    step("随机对照:同一个 parse,随机字节(长度 0..=8)喂 2 亿次(优化编译,约 4 秒),通过前 4 字节「FUZZ」检查的是 0 次,命中 bug 的是 0 次。而 fuzzer 只用了 11480 次执行就找到了:覆盖率反馈让它能把「走到了新分支的输入」留下来继续变异,一层一层逼近。随机测试每次从零开始,没有这种积累。", t=tl(S(6)), mark=lidx(S(6), '命中 bug 的 0 次'), b=bars([['fuzzer 命中', run['found_at'], f"{run['found_at']:,} 次"], ['随机 0 命中', 200000000, '2 亿次 0 命中']], 200000000, done=[0], mark=[1]), kv=KV([['fuzzer', f"{run['found_at']:,} 次执行命中"], ['随机', '2 亿次 0 次命中']], ['fuzzer'])),
    step("修复(返回 data.get(6).map(…))后再 fuzz 30 秒:Done 约 4177 万次执行(约 31 秒),没有崩溃,退出码 0;覆盖率增长事件只有 11 次,最后一次在 #11757。没有崩溃只说明这 30 秒的这个种子没找到,不是没有 bug 的证明。", t=tl(S(7)), done=lidx(S(7), 'Done', '退出码 0'), kv=KV([['修复后 30 秒', '约 4177 万次执行,无崩溃'], ['覆盖率增长', '11 次']], ['修复后 30 秒'])),
    step("unsafe 的 bug:payload 用 get_unchecked(1 + n),n 来自输入的第一个字节。默认的 cargo fuzz run 带 debug assertions,标准库的检查直接报「unsafe precondition(s) violated: slice::get_unchecked requires that the index is within the slice」,输入 [10, 10]。加 -O(关掉 debug assertions)后改由 ASan 报「heap-buffer-overflow」「READ of size 1」,栈第一帧是 payload lib.rs:22。再加 --sanitizer none:30 秒 8278 万次执行、退出码 0,什么都没报 —— 越界读发生了,但没有人检查。", t=tl(S(8)), mark=lidx(S(8), 'unsafe precondition', 'heap-buffer-overflow', 'READ of size 1'), done=lidx(S(8), 'Done'), kv=KV([['默认', 'debug assertion 报 get_unchecked 前提被违反'], ['-O + ASan', 'heap-buffer-overflow'], ['-O --sanitizer none', '无报告,退出码 0']], ['-O + ASan'])),
    step(f"速度(parse_fixed,20 秒,固定种子):带 ASan(默认){a_['stat::number_of_executed_units']:,} 次,平均 {ea:,} 次/秒;--sanitizer none {n_['stat::number_of_executed_units']:,} 次,平均 {en:,} 次/秒,约 {en / ea:.1f} 倍。覆盖率引导的 fuzz 靠大量执行,所以执行速度很重要;但关掉 sanitizer 会漏掉上一步那样的 bug,需要取舍。", t=tl(S(9)), b=bars([['ASan', ea, f'{ea / 1e6:.2f}M/s'], ['--sanitizer none', en, f'{en / 1e6:.2f}M/s']], en, done=[0, 1]), kv=KV([['ASan', f'{ea:,} 次/秒'], ['--sanitizer none', f'{en:,} 次/秒']], ['--sanitizer none'])),
]
A = mkart('u165', 165, 'Rust,Fuzz,cargo-fuzz,libFuzzer,真实验证,动画演示',
    f'用 cargo-fuzz 0.13.2(libFuzzer)验证:没有初始语料,第 {run["found_at"]:,} 次执行就找到 parse 里「长度恰为 6」的越界 bug(随机输入 2 亿次 0 命中);崩溃输入可重放、已是最小;unsafe 的 get_unchecked 越界默认由 debug assertion、-O 时由 ASan 报告,--sanitizer none 则漏报;ASan 约 {ea / 1e6:.2f}M 次/秒,none 约 {en / 1e6:.2f}M 次/秒。',
    '单元测试只覆盖你想到的输入。Fuzz 测试让程序自己去找:生成输入、观察覆盖率、保留带来新分支的输入再变异。这篇用一个藏了 bug 的小函数,把 cargo fuzz 从建目录到找到崩溃、复现、对比随机测试的过程完整跑一遍。',
    [(f'{run["found_at"]:,}', 'fuzzer 命中越界 bug 所需的执行次数(固定种子)'), ('0 / 2 亿', '随机字节测试 2 亿次命中 bug 的次数'), (f'{en / ea:.1f}×', '--sanitizer none 对默认 ASan 的执行速度比')],
    [('目录与目标', '<p>Fuzz 常与 sanitizer 一起使用,见<a href="rust-sanitizer.html">Sanitizer</a>;cargo-fuzz 使用 nightly 工具链。</p>'), ('运行与覆盖率', None), ('复现', None), ('语料库', None), ('最小化', None), ('随机测试对照', None), ('修复之后', None), ('unsafe 的 bug', '<p>对比用 Miri 检查未定义行为:<a href="rust-miri.html">Miri 检查未定义行为</a>。</p>'), ('速度', None)],
    steps, [ENV_N + '。cargo-fuzz 0.13.2(cargo install --locked,装在隔离目录),libfuzzer-sys 0.4;所有运行固定 -seed=1', '没有验证:Linux 上的表现、cargo fuzz coverage 生成覆盖率报告、结构化输入(arbitrary crate)、字典(-dict)、并行(-jobs/-workers)、长时间(小时级)运行能多发现什么、对更长崩溃输入的 tmin 缩减效果', '本篇的随机对照是自己写的 xorshift 随机字节生成器,不是任何现成的随机测试工具'], 'cargo fuzz')
